const __pageData = JSON.parse('{"title":"Israel Defense Forces","description":"","frontmatter":{"title":"Israel Defense Forces","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["israel","military","iran"],"sources":["raw/badlands-brief-095.md","raw/badlands-brief-143.md","raw/badlands-brief-0fb.md","raw/badlands-brief-282.md","raw/badlands-brief-559.md","raw/badlands-brief-579.md","raw/badlands-brief-5dc.md","raw/badlands-brief-625.md","raw/badlands-brief-6b4.md","raw/badlands-brief-6f0.md","raw/badlands-brief-9ea.md","raw/badlands-brief-b56.md","raw/badlands-brief-c7b.md","raw/badlands-brief-d1a.md","raw/badlands-news-brief-023.md","raw/badlands-news-brief-08a.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-0d4.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-0f0.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-10a.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-2a0.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-362.md","raw/badlands-news-brief-378.md","raw/badlands-news-brief-421.md","raw/badlands-news-brief-525.md","raw/badlands-news-brief-576.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-786.md","raw/badlands-news-brief-7c6.md","raw/badlands-news-brief-845.md","raw/badlands-news-brief-889.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/israel-defense-forces.md","filePath":"entities/israel-defense-forces.md","lastUpdated":null}');
